{
  "implementation": "def solve(case):
    # Validate required fields
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("Missing 'nodes' or 'required_symbols' in case payload")
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("Invalid types: nodes must be list, required_symbols must be list")

    # Build maps
    id_to_node = {}
    children = {}  # id -> list of child ids
    for node in nodes:
        nid = node['id']
        if not isinstance(nid, str):
            raise ValueError("Node id must be string")
        id_to_node[nid] = node
        parent = node.get('parent')
        if parent is not None:
            children.setdefault(parent, []).append(nid)
        else:
            # root has no parent; ensure children list exists
            children.setdefault(nid, [])

    # Precompute subtree sets (including node itself)
    subtree = {}
    def dfs(nid):
        if nid in subtree:
            return subtree[nid]
        s = {nid}
        for c in children.get(nid, []):
            s |= dfs(c)
        subtree[nid] = s
        return s

    for nid in id_to_node:
        dfs(nid)

    # Initial retained set: all nodes
    retained = set(id_to_node.keys())
    # Track removed node ids in order
    removed = []

    # Sort nodes: deeper first, tie by id
    sorted_nodes = sorted(id_to_node.values(), key=lambda x: (-x['depth'], x['id']))

    for node in sorted_nodes:
        nid = node['id']
        # Skip if not removable or is root (though root removable is false, double-check)
        if not node.get('removable', False) or node['depth'] == 0:
            continue
        # Check that no child of this node is retained
        has_retained_child = False
        for c in children.get(nid, []):
            if c in retained:
                has_retained_child = True
                break
        if has_retained_child:
            continue

        # Compute the set of nodes in subtree that are currently retained
        sub_retained = subtree[nid] & retained
        if not sub_retained:
            # already removed
            continue

        # Check required_symbols: for each required symbol, ensure that
        # after removing sub_retained, at least one node with that symbol remains
        # Count occurrences in current retained set
        total_counts = {}
        for rnid in retained:
            sym = id_to_node[rnid]['symbol']
            if sym in required_symbols:
                total_counts[sym] = total_counts.get(sym, 0) + 1
        # Count occurrences in sub_retained
        sub_counts = {}
        for rnid in sub_retained:
            sym = id_to_node[rnid]['symbol']
            if sym in required_symbols:
                sub_counts[sym] = sub_counts.get(sym, 0) + 1
        # Check deficiency
        can_remove = True
        for sym in required_symbols:
            total = total_counts.get(sym, 0)
            sub = sub_counts.get(sym, 0)
            if sub == total:
                can_remove = False
                break
        if not can_remove:
            continue

        # Perform removal
        retained -= sub_retained
        removed.append(nid)

    # Build output
    removed_sorted = sorted(removed)
    retained_sorted = sorted(retained)
    return {
        "removed_node_ids": removed_sorted,
        "retained_node_ids": retained_sorted
    }"
}
